class NaiveLogger {
    private Level level = Level.INFO;
    private final PrintWriter out;
    NaiveLogger(PrintWriter out) { this.out = out; }
    public synchronized void log(Level l, String msg) {
        if (l.severity < level.severity) return;
        // BAD: formatting + I/O on caller thread under lock.
        out.println(System.currentTimeMillis() + " [" + l + "] " + msg);
    }
}

import java.io.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;

enum Level { DEBUG(10), INFO(20), WARN(30), ERROR(40), FATAL(50);
    final int severity; Level(int s) { this.severity = s; }
    boolean enables(Level e) { return e.severity >= severity; }
}

final class LogRecord {
    final long epochMillis;
    final String loggerName;
    final Level level;
    final String message;
    final String threadName;
    final Map<String, String> context;
    LogRecord(String loggerName, Level level, String message, Map<String,String> ctx) {
        this.epochMillis = System.currentTimeMillis();
        this.loggerName = loggerName;
        this.level = level;
        this.message = message == null ? "null" : message;
        this.threadName = Thread.currentThread().getName();
        this.context = ctx == null ? Map.of() : Map.copyOf(ctx);
    }
}

interface Formatter { String format(LogRecord r); }

final class PatternFormatter implements Formatter {
    public String format(LogRecord r) {
        // Keep allocation obvious; JSON formatter is a drop-in replacement.
        return Instant.ofEpochMilli(r.epochMillis) + " [" + r.threadName + "] "
            + r.level + " " + r.loggerName + " " + r.message
            + (r.context.isEmpty() ? "" : " " + r.context);
    }
}

interface Appender extends Closeable {
    void append(LogRecord r); // must never throw to caller
}

final class ConsoleAppender implements Appender {
    private final Formatter fmt;
    ConsoleAppender(Formatter fmt) { this.fmt = fmt; }
    public void append(LogRecord r) {
        try { System.out.println(fmt.format(r)); }
        catch (Exception ignored) { /* never propagate */ }
    }
    public void close() { System.out.flush(); }
}

final class RollingFileAppender implements Appender {
    private final Formatter fmt;
    private final long maxBytes;
    private final String basePath;
    private PrintWriter out;
    private long written;
    RollingFileAppender(String basePath, long maxBytes, Formatter fmt) throws IOException {
        this.basePath = basePath; this.maxBytes = maxBytes; this.fmt = fmt;
        this.out = new PrintWriter(new BufferedWriter(new FileWriter(basePath, true)), false);
    }
    public synchronized void append(LogRecord r) {
        try {
            String line = fmt.format(r);
            if (written + line.length() > maxBytes) rotate();
            out.println(line); out.flush(); // flush per batch in real code
            written += line.length() + 1;
        } catch (Exception ignored) { }
    }
    private void rotate() throws IOException {
        out.close();
        new File(basePath).renameTo(new File(basePath + "." + System.currentTimeMillis()));
        out = new PrintWriter(new BufferedWriter(new FileWriter(basePath, false)), false);
        written = 0;
    }
    public synchronized void close() { out.close(); }
}

// Decorator: makes any appender async with explicit drop policy.
final class AsyncAppender implements Appender {
    private final Appender downstream;
    private final BlockingQueue<LogRecord> q;
    private final Thread worker;
    private volatile boolean running = true;
    private final AtomicLong dropped = new AtomicLong();
    AsyncAppender(Appender downstream, int capacity) {
        this.downstream = downstream;
        this.q = new ArrayBlockingQueue<>(capacity);
        this.worker = new Thread(this::drain, "log-worker");
        this.worker.setDaemon(true);
        this.worker.start();
    }
    public void append(LogRecord r) {
        if (!running) return;
        // Trade-off: offer() never blocks caller; drop-newest keeps latency flat.
        if (!q.offer(r)) dropped.incrementAndGet();
    }
    private void drain() {
        try {
            while (running || !q.isEmpty()) {
                LogRecord r = q.poll(200, TimeUnit.MILLISECONDS);
                if (r != null) {
                    try { downstream.append(r); }
                    catch (Exception ignored) { }
                }
            }
        } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
    public long droppedCount() { return dropped.get(); }
    public void close() throws IOException {
        running = false;
        try { worker.join(3000); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        // Best-effort drain of what is left within the timeout.
        LogRecord r;
        while ((r = q.poll()) != null) { try { downstream.append(r); } catch (Exception ignored) {} }
        downstream.close();
    }
}

final class Logger {
    private final String name;
    private volatile Level level;
    private final CopyOnWriteArrayList<Appender> appenders = new CopyOnWriteArrayList<>();
    Logger(String name, Level level) { this.name = name; this.level = level; }
    public void setLevel(Level l) { this.level = l; }
    public void addAppender(Appender a) { appenders.add(a); }
    public void log(Level l, String msg) { log(l, msg, null); }
    public void log(Level l, String msg, Map<String,String> ctx) {
        if (!level.enables(l)) return; // hot path: single volatile read
        LogRecord rec = new LogRecord(name, l, msg, ctx);
        for (Appender a : appenders) {
            try { a.append(rec); } catch (Exception ignored) { }
        }
    }
    public void info(String m) { log(Level.INFO, m); }
    public void error(String m) { log(Level.ERROR, m); }
    public void debug(String m) { log(Level.DEBUG, m); }
}

final class LoggerFactory {
    private static final ConcurrentMap<String, Logger> REG = new ConcurrentHashMap<>();
    static Logger getLogger(String name) {
        return REG.computeIfAbsent(name, n -> {
            // Hierarchy: inherit from nearest dotted parent if present.
            Level inherited = Level.INFO;
            int dot = n.lastIndexOf('.');
            if (dot > 0) {
                Logger parent = REG.get(n.substring(0, dot));
                if (parent != null) inherited = parent.level;
            }
            return new Logger(n, inherited);
        });
    }
}

import queue, threading, time, sys
from dataclasses import dataclass
from enum import IntEnum

class Level(IntEnum):
    DEBUG=10; INFO=20; WARN=30; ERROR=40; FATAL=50

@dataclass(frozen=True)
class LogRecord:
    logger: str; level: Level; msg: str; thread: str; ts: float

class AsyncAppender:
    def __init__(self, capacity=10000, sink=sys.stdout):
        self.q: queue.Queue = queue.Queue(maxsize=capacity)
        self.sink = sink; self.dropped = 0; self._run = True
        self._t = threading.Thread(target=self._drain, daemon=True)
        self._t.start()
    def append(self, r: LogRecord):
        try: self.q.put_nowait(r)  # never block caller: drop-newest
        except queue.Full: self.dropped += 1
    def _drain(self):
        while self._run or not self.q.empty():
            try: r = self.q.get(timeout=0.2)
            except queue.Empty: continue
            try: print(f"{r.ts:.3f} [{r.thread}] {r.level.name} {r.logger} {r.msg}", file=self.sink)
            except Exception: pass
    def close(self):
        self._run = False; self._t.join(timeout=3)

class Logger:
    def __init__(self, name, level=Level.INFO):
        self.name=name; self.level=level; self.appenders=[]
    def log(self, level, msg):
        if level < self.level: return
        rec = LogRecord(self.name, level, str(msg), threading.current_thread().name, time.time())
        for a in list(self.appenders):
            try: a.append(rec)
            except Exception: pass
